h1 { font-size:30px; font-weight:900; margin-bottom:6px; }
h1 span { color:var(--gold); }
.sub { color:rgba(255,255,255,.5); font-size:16px; margin-bottom:18px; }
.toolbar { display:flex; gap:12px; align-items:center; margin-bottom:28px; flex-wrap:wrap; }
.btn-copy {
  background:rgba(200,169,110,.12); border:1px solid var(--gold); color:var(--gold);
  font-family:inherit; font-size:14px; font-weight:900; padding:10px 18px; border-radius:10px;
  cursor:pointer; transition:.2s;
}
.btn-copy:hover { background:rgba(200,169,110,.25); }
.toast {
  position:fixed; bottom:28px; left:50%; transform:translateX(-50%) translateY(20px);
  background:var(--gold); color:#151107; font-weight:900; font-size:15px;
  padding:14px 28px; border-radius:12px; opacity:0; pointer-events:none;
  transition:.25s; z-index:999; box-shadow:0 8px 24px rgba(0,0,0,.4);
}
.toast.show { opacity:1; transform:translateX(-50%) translateY(0); }
.section-title {
  display:flex; align-items:center; gap:12px; margin:40px 0 16px;
  font-size:20px; font-weight:900; color:var(--gold);
}
.section-title .count { font-size:14px; color:rgba(255,255,255,.4); font-weight:700; }
.section-title::after { content:''; flex:1; height:1px; background:var(--line); }
.section-drag-handle {
  flex-shrink:0; width:20px; text-align:center; cursor:grab; user-select:none;
  color:rgba(255,255,255,.3); font-size:16px; letter-spacing:-2px; transition:.2s; touch-action:none;
}
.section-drag-handle:hover { color:var(--gold); }
.section-drag-handle:active { cursor:grabbing; }
.section-block.section-dragging { opacity:.4; border:1px dashed var(--gold); border-radius:12px; }
.grid { display:flex; flex-direction:column; gap:8px; }
.item {
  display:flex; align-items:center; gap:12px; color:#fff;
  background:var(--dark2); border:1px solid var(--line); border-radius:10px;
  padding:10px 14px 10px 8px; transition:border-color .2s, background .2s;
}
.item:hover { border-color:var(--gold); background:#1a1a1a; }
.item.dragging { opacity:.35; border-style:dashed; }
.drag-handle {
  flex-shrink:0; width:28px; height:34px; display:flex; align-items:center; justify-content:center;
  color:rgba(255,255,255,.3); cursor:grab; font-size:18px; letter-spacing:-2px; touch-action:none;
  border-radius:6px; transition:.2s;
}

