/* ===== Rules Full CTA + Modal (完整守則) ===== */
#rules-full-link { text-align: center; padding: 8px 0 48px; }
.rules-full-cta {
  display: inline-block;
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.1em;
  color: var(--gold);
  text-decoration: none;
  padding: 10px 28px;
  border: 1px solid var(--gold-border);
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, rgba(200,162,75,0.12), transparent);
  background-size: 200% 100%;
  animation: rulesShimmer 2.4s linear infinite, rulesGlowPulse 2.2s ease-in-out infinite;
  cursor: pointer;
  transition: transform 0.25s, border-color 0.25s;
}
.rules-full-cta:hover { transform: translateY(-2px) scale(1.03); border-color: var(--gold); }
@keyframes rulesShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@keyframes rulesGlowPulse {
  0%, 100% { box-shadow: 0 0 6px rgba(200,162,75,0.25), 0 0 0 rgba(200,162,75,0); }
  50% { box-shadow: 0 0 18px rgba(200,162,75,0.55), 0 0 30px rgba(200,162,75,0.15); }
}

#rules-modal {
  display: none;

