// ===== RULES MODAL (完整守則) =====
(function() {
  window.openRulesModal = function() {
    var m = document.getElementById('rules-modal');
    if (m) m.classList.add('open');
    document.body.style.overflow = 'hidden';
  };
  window.closeRulesModal = function() {
    var m = document.getElementById('rules-modal');
    if (m) m.classList.remove('open');
    document.body.style.overflow = '';
  };
  window.closeRulesModalBg = function(e) {
    if (e.target === document.getElementById('rules-modal')) window.closeRulesModal();
  };
  document.addEventListener('keydown', function(e) {
    var m = document.getElementById('rules-modal');
    if (m && m.classList.contains('open') && e.key === 'Escape') window.closeRulesModal();
  });
})();

